/* test_gs_cal.c — every flash copy of the garage shadow (app/gs_cal.c,
 * GENERATED by tools/gen_gs_cal.py) byte for byte against the pristine stock
 * image; exit 77 (skipped) when the image is absent */
#include "app/gs_cal.h"
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    FILE *f = fopen(TCU_STOCK_IMAGE, "rb");
    static unsigned char img[0x200000];
    unsigned bad = 0u, bytes = 0u;
    if (f == NULL) {
        printf("SKIP no stock image %s\n", TCU_STOCK_IMAGE);
        return 77;
    }
    if (fread(img, 1u, sizeof img, f) != sizeof img) {
        fclose(f);
        printf("FAIL short image\n");
        return 1;
    }
    fclose(f);
    for (unsigned i = 0u; i < GS_NBLOBS; i++) {
        const gs_blob_t *b = &GS_BLOBS[i];
        for (unsigned j = 0u; j < b->len; j++) {
            bytes++;
            if (b->data[j] != img[b->addr + j]) {
                bad++;
            }
        }
        if (gs_cal_lookup(b->addr, b->len) != b->data) {
            bad++;
        }
    }
    printf("gs_cal: %u blobs, %u bytes, %u differ from the image\n", GS_NBLOBS, bytes, bad);
    return bad == 0u ? 0 : 1;
}
